from dataclasses import dataclass

@dataclass
class Record:
    value: object
    version: int
    fence: int
    committed: bool

class FencedLeaseCoordinator:
    def __init__(self):
        self.epoch = 0
        self.owner = None

    def grant(self, owner):
        self.epoch += 1
        self.owner = owner
        return self.epoch

    def valid(self, owner, fence):
        return self.owner == owner and fence == self.epoch

class QuorumReplica:
    def __init__(self):
        self.data = {}

    def prepare(self, key, value, version, fence):
        old = self.data.get(key)
        if old is not None and fence < old.fence:
            return False
        if old is not None and version < old.version:
            return False
        self.data[key] = Record(value, version, fence, False)
        return True

    def commit(self, key, version, fence):
        item = self.data.get(key)
        if item is None or item.version != version or item.fence != fence:
            return False
        item.committed = True
        return True

    def read_committed(self, key):
        item = self.data.get(key)
        return item if item is not None and item.committed else None

class QuorumCache:
    def __init__(self, replicas, leases):
        self.replicas = replicas
        self.leases = leases
        self.local = {}

    def write(self, key, value, owner):
        fence = self.leases.grant(owner)
        old = [r.read_committed(key) for r in self.replicas]
        old = [x for x in old if x is not None]
        version = max([x.version for x in old] or [0]) + 1
        prepared = [r for r in self.replicas if r.prepare(key, value, version, fence)]
        if len(prepared) < len(self.replicas) // 2 + 1:
            return False
        if not self.leases.valid(owner, fence):
            return False
        committed = [r for r in prepared if r.commit(key, version, fence)]
        if len(committed) < len(self.replicas) // 2 + 1:
            return False
        record = Record(value, version, fence, True)
        self.local[key] = record
        return True

    def read(self, key):
        replies = [r.read_committed(key) for r in self.replicas]
        replies = [x for x in replies if x is not None]
        if len(replies) < len(self.replicas) // 2 + 1:
            return None
        return max(replies, key=lambda x: x.version)
